package org.fuin.porelo.release;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.jspecify.annotations.Nullable;

/** Builds both pages from the same ordered plan and issue snapshot. */
final class PlanRender {
    static final String GENERATED_MARKER =
            "<!-- Generated by porelo-release plan render; do not edit. -->";

    private PlanRender() {}

    /** A render's two serializations, with no clock or machine-specific paths. */
    record Pages(String markdown, String html, Map<String, String> images) {}

    static Map<String, IssueIndex> indexes(Plan plan, Plan.Project project, IssueLinks links)
            throws IOException, Stop {
        final Set<String> repositories = new LinkedHashSet<>();
        for (final Plan.Sprint sprint : plan.sprints()) {
            for (final Plan.Function function : sprint.functions()) {
                function.issues().forEach(issue -> repositories.add(issue.split("#")[0]));
            }
        }
        final Map<String, IssueIndex> issues = new LinkedHashMap<>();
        for (final String repository : repositories) {
            links.issueIndex(project.root(), repository)
                    .forEach((number, row) -> issues.put(repository + "#" + number, row));
        }
        return Map.copyOf(issues);
    }

    static Path page(Path file, Plan plan) {
        return file.toAbsolutePath().resolveSibling(plan.release() + ".md");
    }

    static void write(Path file, Plan plan, Pages pages, @Nullable Path html, Set<Path> inputs)
            throws IOException, Stop {
        final Map<Path, String> outputs = new LinkedHashMap<>();
        outputs.put(page(file, plan), pages.markdown());
        pages.images()
                .forEach(
                        (name, svg) ->
                                outputs.put(file.toAbsolutePath().resolveSibling(name), svg));
        final Path directory =
                java.util.Objects.requireNonNull(file.toAbsolutePath().getParent()).toRealPath();
        for (final Path output : outputs.keySet()) {
            if (!destination(output).startsWith(directory)) {
                throw Stop.refused("Output resolves outside plan directory: " + output);
            }
        }
        if (html != null) {
            for (final Path output : outputs.keySet()) {
                if (sameFile(output, html)) {
                    throw Stop.refused(
                            "HTML output must differ from generated page or image: " + html);
                }
            }
            outputs.put(html, pages.html());
        }
        final var paths = new java.util.ArrayList<>(outputs.keySet());
        for (int i = 0; i < paths.size(); i++) {
            final Path output = paths.get(i);
            for (final Path input : inputs) {
                if (sameFile(input, output)) {
                    throw Stop.refused("Output must differ from input: " + input);
                }
            }
            for (int j = 0; j < i; j++) {
                final Path previous = destination(paths.get(j));
                final Path current = destination(output);
                if (sameFile(paths.get(j), output)
                        || previous.startsWith(current)
                        || current.startsWith(previous)) {
                    throw Stop.refused("Outputs must differ: " + paths.get(j) + " and " + output);
                }
            }
        }
        for (final var output : outputs.entrySet()) {
            Files.createDirectories(
                    java.util.Objects.requireNonNull(output.getKey().toAbsolutePath().getParent()));
            Files.writeString(output.getKey(), output.getValue());
        }
    }

    private static Path destination(Path file) throws IOException {
        Path absolute = file.toAbsolutePath();
        final Set<Path> visited = new LinkedHashSet<>();
        while (Files.isSymbolicLink(absolute)) {
            if (!visited.add(absolute) || visited.size() > 40) {
                throw new IOException("Output symlink chain cannot be resolved: " + file);
            }
            absolute = absolute.resolveSibling(Files.readSymbolicLink(absolute));
        }
        if (Files.exists(absolute)) {
            return absolute.toRealPath();
        }
        return destination(java.util.Objects.requireNonNull(absolute.getParent()))
                .resolve(absolute.getFileName())
                .normalize();
    }

    private static boolean sameFile(Path first, Path second) throws IOException {
        return destination(first).equals(destination(second))
                || (Files.exists(first) && Files.exists(second) && Files.isSameFile(first, second));
    }

    static Pages render(Plan plan, Map<String, IssueIndex> issues, String stand) {
        final PlanTemplate model = PlanTemplate.from(plan, issues, stand);
        final Map<String, String> images = new LinkedHashMap<>();
        images.put(plan.release() + "/progress.svg", template("progress.jte", model));
        final Page page = new Page();
        page.markdown.append(GENERATED_MARKER).append("\n");
        page.heading(1, "Release " + model.release());
        page.text(model.goal());
        page.markdown.append("*Stand: ").append(markdown(model.stand())).append("*\n\n");
        page.heading(2, "Sprint progress");
        final String counts =
                model.sprints().stream()
                        .map(sprint -> "Sprint " + sprint.id() + ": " + sprint.counts())
                        .collect(java.util.stream.Collectors.joining("; "));
        page.markdown
                .append("![")
                .append(alt(counts))
                .append("](")
                .append(model.release())
                .append("/progress.svg)\n\n");
        page.text(PlanTemplate.INTRODUCTION);
        page.heading(2, "Issues Details");
        for (final PlanTemplate.Sprint sprint : model.sprints()) {
            // Markdown has no box of its own; a table of one cell is drawn framed by GitHub and by
            // editors' views,
            // as the HTML page frames a sprint. The blank lines let the Markdown inside it be read
            // as Markdown.
            page.markdown.append("<table><tr><td>\n\n");
            page.heading(3, "Sprint " + sprint.id() + ": " + sprint.title());
            page.text(sprint.goal());
            for (final PlanTemplate.Function function : sprint.functions()) {
                page.markdown
                        .append("**")
                        .append(markdown(function.title()))
                        .append(' ')
                        .append(
                                function.tested().isEmpty()
                                        ? "⚪ Not tested"
                                        : "✅ Tested " + function.tested())
                        .append("**\n\n");
                page.text("Test: " + function.test());
                for (int i = 0; i < function.chips().size(); i++) {
                    if (i > 0) page.markdown.append(' ');
                    page.chip(function.chips().get(i));
                }
                if (!function.chips().isEmpty()) page.markdown.append("\n\n");
            }
            page.markdown.append("</td></tr></table>\n\n");
        }
        return new Pages(
                page.markdown.toString(),
                template("plan.jte", model),
                java.util.Collections.unmodifiableMap(images));
    }

    static String template(String name, Object model) {
        final var output = new gg.jte.output.StringOutput();
        gg.jte.TemplateEngine.createPrecompiled(gg.jte.ContentType.Html)
                .render(name, model, output);
        return output.toString();
    }

    static String alt(String text) {
        return text.replace("\\", "\\\\")
                .replace("[", "\\[")
                .replace("]", "\\]")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\n", " ")
                .replace("\r", " ");
    }

    private static String markdown(String text) {
        return text.replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("|", "\\|")
                // A backslash of the text's own before an image's start would pair with the escape;
                // each such
                // backslash is escaped too, so the exclamation mark stays escaped and the image
                // stays text.
                .replaceAll("(\\\\*)!\\[", "$1$1\\\\![")
                .replaceAll("`{3,}|~{3,}", "\\\\$0")
                .replace("\n", " ")
                .replace("\r", " ")
                .replaceFirst("^( {0,3})(#|[*+\\-](?=\\s|$))", "$1\\\\$2")
                .replaceFirst("^( {0,3}\\d{1,9})\\.(?=\\s|$)", "$1\\\\.");
    }

    private static final class Page {
        private final StringBuilder markdown = new StringBuilder();

        void heading(int level, String text) {
            markdown.append("#".repeat(level)).append(' ').append(markdown(text)).append("\n\n");
        }

        void text(String text) {
            markdown.append(markdown(text)).append("\n\n");
        }

        void chip(PlanTemplate.Chip chip) {
            markdown.append(chip.emoji()).append(' ');
            if (chip.link().isEmpty()) {
                markdown.append(inline(chip.text()));
            } else {
                markdown.append('[')
                        .append(inline(chip.text()))
                        .append("](")
                        .append(chip.link())
                        .append(" \"")
                        .append(title(chip.detail()))
                        .append("\")");
            }
        }
    }

    private static String inline(String text) {
        return text.replace("\\", "\\\\")
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("[", "\\[")
                .replace("]", "\\]")
                .replace("*", "\\*")
                .replace("_", "\\_")
                .replace("`", "\\`")
                .replace("|", "\\|")
                .replace("\n", " ")
                .replace("\r", " ");
    }

    private static String title(String text) {
        return text.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("(", "&#40;")
                .replace(")", "&#41;")
                .replace("\\", "&#92;")
                .replace("\n", " ")
                .replace("\r", " ");
    }
}
